/**
 * Circuit library for the dashboard — public/tracks.json, generated by
 * SOFTWARE/tracks/build_tracks.py from the same data the VCU's track_maps.h is
 * built from (a HARDWARE test keeps them in sync).
 *
 * Geometry is real (public GeoJSON, bacinger/f1-circuits, MIT). Speeds, g, steering
 * and straight-mode zones are MODELLED for an illustrative 2026-style car and must
 * be labelled as such wherever they are shown.
 */

export interface TrackCorner { n: number; pos: number; radiusM: number; dir: 'L' | 'R'; speedKmh: number }
export interface TrackZone { start: number; end: number; lengthM?: number }

export interface TrackDef {
  id: number
  code: string
  grandPrix: string
  name: string
  fullName: string
  location: string
  lengthM: number
  model: { lapTimeS: number; lapTimeCornerModeOnlyS: number; vmaxKmh: number; vminKmh: number; maxLatG: number; straightModeFraction: number }
  polyline: [number, number][]
  series: { speedKmh: number[]; steerDeg: number[]; latG: number[]; longG: number[]; kappa: number[]; straight: boolean[]; braking: boolean[] }
  straightZones: TrackZone[]
  brakeZones: TrackZone[]
  corners: TrackCorner[]
  sectors: number[]
}

export interface TrackDoc {
  version: number
  defaultTrackId: number
  points: number
  attribution: string
  vehicleModel: Record<string, number>
  tracks: TrackDef[]
}

let cache: Promise<TrackDoc> | null = null

export function loadTracks(): Promise<TrackDoc> {
  if (!cache) {
    cache = fetch('/tracks.json').then((r) => {
      if (!r.ok) throw new Error(`tracks.json ${r.status}`)
      return r.json() as Promise<TrackDoc>
    })
    cache.catch(() => { cache = null })
  }
  return cache
}

export function wrap01(p: number): number {
  if (!Number.isFinite(p)) return 0
  return p - Math.floor(p)
}

export function idxAt(t: TrackDef, pos: number): number {
  const n = t.series.speedKmh.length
  return Math.min(n - 1, Math.floor(wrap01(pos) * n))
}

/** Interpolated (x, y) on the centreline in metres. */
export function pointAt(t: TrackDef, pos: number): [number, number] {
  const n = t.polyline.length
  const x = wrap01(pos) * n
  const i0 = Math.floor(x) % n
  const i1 = (i0 + 1) % n
  const w = x - Math.floor(x)
  const a = t.polyline[i0]
  const b = t.polyline[i1]
  return [a[0] + (b[0] - a[0]) * w, a[1] + (b[1] - a[1]) * w]
}

/** Heading (radians, SVG coordinates with y flipped) at pos. */
export function headingAt(t: TrackDef, pos: number): number {
  const a = pointAt(t, pos)
  const b = pointAt(t, pos + 1 / t.polyline.length)
  return Math.atan2(-(b[1] - a[1]), b[0] - a[0])
}

function flagAt(t: TrackDef, pos: number) {
  return t.series.straight[idxAt(t, pos)]
}

/** Same rule as the VCU's trackSample(): the map flag, shrunk by the offsets. */
export function straightAt(t: TrackDef, pos: number, openDelayM = 0, closeEarlyM = 0): boolean {
  return flagAt(t, pos) && flagAt(t, pos - openDelayM / t.lengthM) && flagAt(t, pos + closeEarlyM / t.lengthM)
}

export function sampleAt(t: TrackDef, pos: number) {
  const i = idxAt(t, pos)
  return {
    speedKmh: t.series.speedKmh[i],
    steerDeg: t.series.steerDeg[i],
    latG: t.series.latG[i],
    longG: t.series.longG[i],
    straight: t.series.straight[i],
    braking: t.series.braking[i],
    sector: Math.min(2, Math.floor(wrap01(pos) * 3)),
  }
}

export function cornerNear(t: TrackDef, pos: number, window = 0.02): TrackCorner | null {
  let best: TrackCorner | null = null
  let bestD = window
  for (const c of t.corners) {
    const d = Math.abs(((c.pos - pos + 1.5) % 1) - 0.5)
    if (d < bestD) { best = c; bestD = d }
  }
  return best
}

export function nextEvent(t: TrackDef, pos: number, openDelayM = 0, closeEarlyM = 0) {
  const n = t.series.straight.length
  const now = straightAt(t, pos, openDelayM, closeEarlyM)
  for (let k = 1; k < n; k++) {
    const p = pos + k / n
    if (straightAt(t, p, openDelayM, closeEarlyM) !== now) {
      return { type: now ? 'corner mode' : 'straight mode', inM: (k / n) * t.lengthM, corner: cornerNear(t, p + 0.01) }
    }
  }
  return null
}

/** Firmware defaults (vcu_logic.h Tunables{}), used until the VCU reports its own. */
export const VCU_DEFAULTS: Record<string, number> = {
  aeroMode: 1, trackId: 12, lapLengthCm: 6000, trackRun: 0,
  straightFrontCdeg: 500, straightRearCdeg: 500, cornerFrontCdeg: 3000, cornerRearCdeg: 3500,
  asymGainCdegPerG: 200, straightOpenDelayM: 0, straightCloseEarlyM: 0,
  dutyCapPermille: 1000, dutyFloorPermille: 350, wingSlewDps: 120, steerGainPermille: 1000,
  currentLimitCa: 200, dynoVmaxCkmh: 0, dynoStartPermille: 0, trackCount: 24, wheelDiameterUm: 70000,
}

export function effectiveConfig(reported?: Record<string, number | boolean> | null): Record<string, number> {
  const out = { ...VCU_DEFAULTS }
  for (const [k, v] of Object.entries(reported ?? {})) if (k in out && typeof v === 'number') out[k] = v
  return out
}

/** The VCU's flap formula (TrackRunner::command), for drawing and simulation. */
export function flapsFor(t: TrackDef, pos: number, cfg: Record<string, number>) {
  const straight = straightAt(t, pos, cfg.straightOpenDelayM, cfg.straightCloseEarlyM)
  const front = (straight ? cfg.straightFrontCdeg : cfg.cornerFrontCdeg) / 100
  const rear = (straight ? cfg.straightRearCdeg : cfg.cornerRearCdeg) / 100
  const latG = sampleAt(t, pos).latG
  const lat = straight ? 0 : Math.max(-10, Math.min(10, (latG * cfg.asymGainCdegPerG) / 100))
  const c = (x: number) => Math.max(0, Math.min(45, x))
  return { straight, wing: { frontLeft: c(front - lat), frontRight: c(front + lat), rearLeft: c(rear - lat), rearRight: c(rear + lat) } }
}
